INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('fb5301e6-5596-401b-2917-316da1e9785c', 'Education & Training', 'Our comprehensive training programs combine classroom education with real-world scenarios at mock jobsites. Learn best practices, understand utility marking standards, and master the 811 process.', 'training.html', '🎓', 0);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('ee8d2d36-8794-6c80-94fa-c3bc433515e8', 'Utility Locate Rodeo', 'The Utility Locate Rodeo is an annual competition that showcases the locating profession and encourages best practices among utility locators. This event recognizes excellence and promotes safety.', 'utility-locate-rodeo.html', '🏆', 1);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('d7c68fb1-a74f-c6ea-1594-55d746a63377', 'Silver Shovel Awards', 'The Silver Shovel Awards recognize excavators and contractors who demonstrate strong safety ethics and consistent best practices in damage prevention. Celebrate excellence in our industry.', 'silver-shovel-award.html', '⭐', 2);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('48f2d9df-fda8-7bbe-a4f5-815595a9009d', '811 Day (August 11)', '811 Day is an annual public awareness campaign held on August 11th (8/11) to promote the importance of calling 811 before digging. This nationwide initiative helps prevent utility damage.', '811-day.html', '📅', 3);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('9ebdf422-4dcc-f83e-5dcd-f60de87ae5b3', 'Golf Tournament Fundraiser', 'The NRCGA Golf Tournament is an annual fundraising event that brings together members of Nevada''s damage prevention community for a day of golf, networking, and fun.', 'golf-tournament.html', '⛳', 4);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('40d8fdee-739a-0e67-4ef3-3c162c1137ef', 'Craig Rogers Award', 'The Craig Rogers Award honors excellence in damage prevention in memory of our dear friend and colleague. This award celebrates leaders who demonstrate outstanding commitment to safety.', 'craig-rogers-award.html', '🎖️', 5);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('685de7e3-921f-e154-d32a-fa11f44d4475', 'Operations', 'The Operations working group plays a critical role in ensuring the effective operation of Nevada''s One Call Center system. This group brings together stakeholders to discuss operational improvements.', 'operations.html', '⚙️', 6);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('c44aabcc-1f1a-e3bc-4760-fcf80919ee3b', 'Embedded Facilities Taskforce', 'The Embedded Facilities Taskforce is a technical working group focused on addressing the unique challenges associated with embedded facilities and infrastructure.', 'embedded-facilities-taskforce.html', '⛏', 7);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('a4c87192-c12f-c143-cf71-1410e5fd5737', 'Budget Committee', 'The Budget Committee oversees NRCGA''s financial planning, budget development, and fiscal responsibility to ensure the organization''s long-term sustainability.', 'budget-committee.html', '💰', 8);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('1f447844-bd51-528e-982b-e12829022a9e', 'Technical Solutions Committee', 'The Technical Solutions Committee evaluates and develops innovative technologies and methods to improve damage prevention practices across Nevada.', 'technical-solutions-committee.html', '🔧', 9);
