     VALUES ('00000000-0000-4000-8000-0000b7569434', 'golf-tournament', 'Golf Tournament Fundraiser', 'NRCGA Programs', 'Proceeds support outreach, education, and damage prevention programs statewide.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/golf/NRCGAGolf.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The NRCGA Golf Tournament is an annual fundraising event that brings together members of Nevada''s damage prevention community for a day of golf, networking, and fun. Proceeds from the tournament directly support NRCGA''s outreach, education, and damage prevention programs across the state.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"How Your Support Helps","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• ✓ Funds safety training programs for excavators and locators\n• ✓ Supports community outreach and public awareness campaigns\n• ✓ Enables recognition programs like the Silver Shovel Awards\n• ✓ Helps organize events like 811 Day and the Utility Locate Rodeo","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Tournament Details","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The NRCGA Golf Tournament typically includes:","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":2,"gap":"md","items":[{"icon":"✓","title":"18-Hole Tournament","body":"Scramble format with prizes for top teams"},{"icon":"✓","title":"Networking Opportunities","body":"Connect with industry professionals and stakeholders"},{"icon":"✓","title":"Sponsorship Packages","body":"Multiple sponsorship levels available for businesses"},{"icon":"✓","title":"Awards & Recognition","body":"Prizes, raffles, and recognition for participants"}]}]}]', '<!-- Hero Image Background -->
    <section style="position: relative; height: 60vh; min-height: 400px; background-image: url(''assets/images/programs/golf/NRCGAGolf.jpg''); background-size: cover; background-position: center; background-attachment: fixed; background-repeat: no-repeat;">
        <div style="position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0, 0, 0, 0.4);"></div>
    </section>

    <!-- Main Content -->
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem; margin-top: 2rem;">
                    The NRCGA Golf Tournament is an annual fundraising event that brings together members of Nevada''s damage prevention community for a day of golf, networking, and fun. Proceeds from the tournament directly support NRCGA''s outreach, education, and damage prevention programs across the state.
                </p>

                <div style="background: var(--bg-light); padding: 2rem; border-radius: 12px; margin: 2rem 0;">
                    <h3 style="margin-bottom: 1.5rem; color: var(--primary);">How Your Support Helps</h3>
                    <ul style="list-style: none; padding: 0; display: flex; flex-direction: column; gap: 1rem;">
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Funds safety training programs for excavators and locators</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Supports community outreach and public awareness campaigns</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Enables recognition programs like the Silver Shovel Awards</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Helps organize events like 811 Day and the Utility Locate Rodeo</span>
                        </li>
                    </ul>
                </div>

                <h2 style="margin-top: 3rem; margin-bottom: 1.5rem;">Tournament Details</h2>
                <p style="margin-bottom: 2rem; color: var(--text-light);">
                    The NRCGA Golf Tournament typically includes:
                </p>

                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem; margin-top: 2rem;">
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">18-Hole Tournament</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Scramble format with prizes for top teams</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Networking Opportunities</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Connect with industry professionals and stakeholders</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Sponsorship Packages</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Multiple sponsorship levels available for businesses</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Awards & Recognition</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Prizes, raffles, and recognition for participants</p>
                    </div>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, body_html, regions_json, published, is_custom)
     VALUES ('00000000-0000-4000-8000-000059599137', 'utility-locate-rodeo', 'Utility Locate Rodeo', 'NRCGA Programs', 'Competition that showcases the locating profession and encourages best practices among utility locators', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/locate rodeo/StcHYFS3_1000x667.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":3,"text":"About the Competition","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"The Utility Locate Rodeo is an annual competition that brings together utility locators from across Nevada to demonstrate their skills, share knowledge, and celebrate excellence in damage prevention.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Participants compete in various challenges that test their expertise in identifying and marking underground utilities, their knowledge of best practices, and their accuracy. This event not only recognizes outstanding performance but also serves as an educational opportunity for the entire damage prevention community.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Event Highlights","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"grid","columns":3,"gap":"md","items":[{"icon":"✓","title":"Skills Competition","body":"Locators demonstrate their expertise in identifying and marking underground utilities accurately and efficiently."},{"icon":"✓","title":"Best Practices Showcase","body":"Participants share knowledge and techniques that promote safety and accuracy in utility locating."},{"icon":"✓","title":"Networking & Education","body":"Connect with peers, learn from industry experts, and stay updated on the latest technologies and techniques."},{"icon":"✓","title":"Recognition & Awards","body":"Outstanding performers are recognized for their excellence in utility locating and damage prevention."}]}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/locate rodeo/wJysU-NA.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The Utility Locate Rodeo is organized by the NRCGA''s Utility Locate Rodeo Committee. Whether you''re interested in participating as a competitor, volunteering, or sponsoring the event, we''d love to have you involved.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":2,"gap":"md","items":[{"icon":"✓","title":"Participate","body":"Register as a competitor and showcase your locating skills."},{"icon":"✓","title":"Volunteer","body":"Help organize and run the event as a volunteer."},{"icon":"✓","title":"Sponsor","body":"Support the event as a sponsor."}]}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/locate rodeo/NRCGA-Utility_Locate_Rodeo-Logo.png","alt":"NRCGA Utility Locate Rodeo Logo","caption":"","width":"full","align":"left"},{"type":"heading","level":2,"text":"Utility Locate Rodeo Committee","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The Utility Locate Rodeo is planned and executed by dedicated volunteers from the NRCGA''s Utility Locate Rodeo Committee. This committee works year-round to organize the annual competition, coordinate logistics, and ensure a successful event that benefits the entire damage prevention community.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"If you''re interested in joining the committee or learning more about how the rodeo is organized, please contact us.","style":{"align":"left","textSize":"md","textColor":"default"}}]}]', '<!-- Hero Image Background -->
    <section style="position: relative; height: 60vh; min-height: 400px; background-image: url(''assets/images/programs/locate rodeo/StcHYFS3_1000x667.jpg''); background-size: cover; background-position: center; background-attachment: fixed; background-repeat: no-repeat;">
        <div style="position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0, 0, 0, 0.4);"></div>
    </section>

    <!-- Main Content -->
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <div style="background: var(--bg-light); padding: 2rem; border-radius: 12px; margin: 2rem 0; margin-top: 2rem; border-left: 4px solid var(--primary);">
                    <h3 style="margin-bottom: 1rem; color: var(--primary);">About the Competition</h3>
                    <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 1rem;">
                        The Utility Locate Rodeo is an annual competition that brings together utility locators from across Nevada to demonstrate their skills, share knowledge, and celebrate excellence in damage prevention.
                    </p>
                    <p style="font-size: 1.125rem; line-height: 1.8;">
                        Participants compete in various challenges that test their expertise in identifying and marking underground utilities, their knowledge of best practices, and their accuracy. This event not only recognizes outstanding performance but also serves as an educational opportunity for the entire damage prevention community.
                    </p>
                </div>

                <h2 style="margin-top: 3rem; margin-bottom: 1.5rem;">Event Highlights</h2>
                <div style="display: grid; gap: 1.5rem; margin-top: 2rem;">
                    <div style="padding: 1.5rem; background: var(--bg-light); border-radius: 8px;">
                        <h3 style="margin-bottom: 0.75rem; color: var(--primary);">Skills Competition</h3>
                        <p>Locators demonstrate their expertise in identifying and marking underground utilities accurately and efficiently.</p>
                    </div>
                    <div style="padding: 1.5rem; background: var(--bg-light); border-radius: 8px;">
                        <h3 style="margin-bottom: 0.75rem; color: var(--primary);">Best Practices Showcase</h3>
                        <p>Participants share knowledge and techniques that promote safety and accuracy in utility locating.</p>
                    </div>
                    <div style="padding: 1.5rem; background: var(--bg-light); border-radius: 8px;">
                        <h3 style="margin-bottom: 0.75rem; color: var(--primary);">Networking & Education</h3>
                        <p>Connect with peers, learn from industry experts, and stay updated on the latest technologies and techniques.</p>
                    </div>
                    <div style="padding: 1.5rem; background: var(--bg-light); border-radius: 8px;">
                        <h3 style="margin-bottom: 0.75rem; color: var(--primary);">Recognition & Awards</h3>
                        <p>Outstanding performers are recognized for their excellence in utility locating and damage prevention.</p>
                    </div>
                </div>
                
            </div>
        </div>
    </section>

    <!-- Background Image Section -->
    <section style="position: relative; height: 50vh; min-height: 350px; background-image: url(''assets/images/programs/locate rodeo/wJysU-NA.jpg''); background-size: cover; background-position: center; background-attachment: fixed; background-repeat: no-repeat;">
        <div style="position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0, 0, 0, 0.3);"></div>
    </section>

    <!-- Get Involved -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <h2>Get Involved</h2>
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    The Utility Locate Rodeo is organized by the NRCGA''s Utility Locate Rodeo Committee. Whether you''re interested in participating as a competitor, volunteering, or sponsoring the event, we''d love to have you involved.
                </p>
                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem; margin-top: 2rem;">
                    <div style="padding: 2rem; background: white; border-radius: 8px; text-align: center;">
                        <h3 style="margin-bottom: 1rem; color: var(--primary);">Participate</h3>
                        <p style="margin-bottom: 1.5rem; color: var(--text-light);">Register as a competitor and showcase your locating skills.</p>
                        <a href="contact.html" class="btn btn-primary">Register to Compete</a>
                    </div>
                    <div style="padding: 2rem; background: white; border-radius: 8px; text-align: center;">
                        <h3 style="margin-bottom: 1rem; color: var(--primary);">Volunteer</h3>
                        <p style="margin-bottom: 1.5rem; color: var(--text-light);">Help organize and run the event as a volunteer.</p>
                        <a href="contact.html" class="btn btn-secondary">Volunteer</a>
                    </div>
                    <div style="padding: 2rem; background: white; border-radius: 8px; text-align: center;">
                        <h3 style="margin-bottom: 1rem; color: var(--primary);">Sponsor</h3>
                        <p style="margin-bottom: 1.5rem; color: var(--text-light);">Support the event as a sponsor.</p>
                        <a href="contact.html" class="btn btn-secondary">Become a Sponsor</a>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- Committee Info -->
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <div style="text-align: center; margin-bottom: 2rem;">
                    <img src="assets/images/programs/locate rodeo/NRCGA-Utility_Locate_Rodeo-Logo.png" alt="NRCGA Utility Locate Rodeo Logo" style="max-width: 400px; width: 100%; height: auto;" onerror="this.style.display=''none''">
                </div>
                <h2>Utility Locate Rodeo Committee</h2>
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    The Utility Locate Rodeo is planned and executed by dedicated volunteers from the NRCGA''s Utility Locate Rodeo Committee. This committee works year-round to organize the annual competition, coordinate logistics, and ensure a successful event that benefits the entire damage prevention community.
                </p>
                <p style="font-size: 1.125rem; line-height: 1.8;">
                    If you''re interested in joining the committee or learning more about how the rodeo is organized, please <a href="contact.html">contact us</a>.
                </p>
            </div>
        </div>
    </section>', NULL, 1, 0);
