     VALUES ('00000000-0000-4000-8000-0000003fd7ec', 'operations', 'Operations', 'NRCGA Programs', 'This group oversees how the One Call Center operates for Nevada and discusses potential changes that could impact its functionality.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The Operations working group plays a critical role in ensuring the effective operation of Nevada''s One Call Center system. This group brings together stakeholders to discuss operational improvements, address challenges, and ensure that the 811 system serves Nevada''s damage prevention community effectively.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Committee Responsibilities","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The Operations working group is made up of dedicated volunteers from across Nevada''s damage prevention community. Members meet regularly to:","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":2,"gap":"md","items":[{"icon":"✓","title":"Review Operations","body":"Monitor One Call Center performance and identify areas for improvement"},{"icon":"✓","title":"Evaluate Changes","body":"Assess proposed changes and their potential impact on system functionality"},{"icon":"✓","title":"Problem Solving","body":"Address operational challenges and develop solutions"},{"icon":"✓","title":"Stakeholder Coordination","body":"Work with utilities, excavators, and other stakeholders on operational matters"}]}]}]', '<!-- Main Content -->
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    The Operations working group plays a critical role in ensuring the effective operation of Nevada''s One Call Center system. This group brings together stakeholders to discuss operational improvements, address challenges, and ensure that the 811 system serves Nevada''s damage prevention community effectively.
                </p>

                <!-- Key responsibilities. This section is commented out
                <div style="background: var(--bg-light); padding: 2rem; border-radius: 12px; margin: 2rem 0;">
                    <h3 style="margin-bottom: 1.5rem; color: var(--primary);">Key Responsibilities</h3>
                    <ul style="list-style: none; padding: 0; display: flex; flex-direction: column; gap: 1rem;">
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Oversee One Call Center operations and performance for Nevada</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Discuss and evaluate potential changes that could impact system functionality</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Address operational challenges and identify improvement opportunities</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Coordinate with USA North 811 and other stakeholders on operational matters</span>
                        </li>
                    </ul>
                </div> -->

                <h2 style="margin-top: 3rem; margin-bottom: 1.5rem;">Committee Responsibilities</h2>
                <p style="margin-bottom: 2rem; color: var(--text-light);">
                    The Operations working group is made up of dedicated volunteers from across Nevada''s damage prevention community. Members meet regularly to:
                </p>

                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem; margin-top: 2rem;">
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Review Operations</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Monitor One Call Center performance and identify areas for improvement</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Evaluate Changes</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Assess proposed changes and their potential impact on system functionality</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Problem Solving</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Address operational challenges and develop solutions</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Stakeholder Coordination</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Work with utilities, excavators, and other stakeholders on operational matters</p>
                    </div>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
