     VALUES ('00000000-0000-4000-8000-0000cdf3811a', 'technical-solutions-committee', 'Technical Solutions Committee', 'NRCGA Programs', 'The Technical Solutions Committee evaluates and develops innovative technologies and methods to improve damage prevention practices across Nevada.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The Technical Solutions Committee focuses on identifying, evaluating, and promoting innovative technologies and methodologies that enhance damage prevention efforts. This committee brings together technical experts to explore solutions that improve locating accuracy, excavation safety, and overall system effectiveness.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"This committee is also the primary steward of the NRCGA website.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Key Responsibilities","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• ✓ Evaluate new technologies for damage prevention applications\n• ✓ Develop technical standards and best practices\n• ✓ Research and test innovative locating and excavation methods\n• ✓ Provide technical guidance to the NRCGA community","style":{"align":"left","textSize":"md","textColor":"default"}}]}]', '<!-- Main Content -->
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    The Technical Solutions Committee focuses on identifying, evaluating, and promoting innovative technologies and methodologies that enhance damage prevention efforts. This committee brings together technical experts to explore solutions that improve locating accuracy, excavation safety, and overall system effectiveness.
                </p>
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    This committee is also the primary steward of the NRCGA website.
                </p>

                <div style="background: var(--bg-light); padding: 2rem; border-radius: 12px; margin: 2rem 0;">
                    <h3 style="margin-bottom: 1.5rem; color: var(--primary);">Key Responsibilities</h3>
                    <ul style="list-style: none; padding: 0; display: flex; flex-direction: column; gap: 1rem;">
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Evaluate new technologies for damage prevention applications</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Develop technical standards and best practices</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Research and test innovative locating and excavation methods</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Provide technical guidance to the NRCGA community</span>
                        </li>
                    </ul>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, body_html, regions_json, published, is_custom)
     VALUES ('00000000-0000-4000-8000-000008417f9d', 'embedded-facilities-taskforce', 'Embedded Facilities Taskforce', 'NRCGA Programs', 'Addresses challenges and solutions related to embedded facilities and infrastructure. This working group focuses on technical solutions for damage prevention.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The Embedded Facilities Taskforce is a technical working group focused on addressing the unique challenges associated with embedded facilities and infrastructure. This group brings together experts from across Nevada''s damage prevention community to develop solutions and best practices for working with embedded utilities.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"This committee is collecting occurrences of embedded underground facilities. If you''ve discovered an embedded facility, please use the form linked below.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Discovered an Embedded Facility?","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to submit your discovery of an embedded facility.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Submit Occurrence","url":"https://forms.gle/eitenb2XvR5xChUU6","style":{"align":"left"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to view your committee enrollment.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Committee Enrollment","url":"committee-enrollment.html","style":{"align":"left"}},{"type":"text","body":"Interested in participating in this program?","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Contact Us","url":"contact.html","style":{"align":"left"}}]}]', '<section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    The Embedded Facilities Taskforce is a technical working group focused on addressing the unique challenges associated with embedded facilities and infrastructure. This group brings together experts from across Nevada''s damage prevention community to develop solutions and best practices for working with embedded utilities.
                </p>

                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    This committee is collecting occurrences of embedded underground facilities. If you''ve discovered an embedded facility, please use the form linked below.
                </p>

                <div style="text-align: center; margin: 3rem 0;">
                    <h2>Discovered an Embedded Facility?</h2>
                    <p>Click here to submit your discovery of an embedded facility.</p>
                    <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 2rem; flex-wrap: wrap;">
                        <a href="https://forms.gle/eitenb2XvR5xChUU6" class="btn btn-primary">Submit Occurrence</a>
                    </div>
                </div>

                <!-- future form
                <div id="form-container-test-form" style="margin: 2rem 0; max-width: 600px; margin-left: auto; margin-right: auto;"></div>
                <script>
                  if (typeof FormRenderer !== ''undefined'') {
                    const formRenderer = new FormRenderer(''test-form'', ''form-container-test-form'');
                    formRenderer.load().then(() => formRenderer.render());
                  }
                </script> -->
            </div>
        </div>
    </section>

    <section class="content-section bg-light">
        <div class="container">
            <div class="cta-content" style="text-align: center;">
                <h2>Get Involved</h2>
                <p>Click here to view your committee enrollment.</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 2rem; flex-wrap: wrap;">
                    <a href="committee-enrollment.html" class="btn btn-primary">Committee Enrollment</a>
                </div>

                <p style="margin-top: 2rem;">Interested in participating in this program?</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 2rem; flex-wrap: wrap;">
                    <a href="contact.html" class="btn btn-primary">Contact Us</a>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
