     VALUES ('00000000-0000-4000-8000-0000b013e218', 'about-811', 'What is 811?', 'Call Before You Dig', '811 is the national "Call Before You Dig" number that connects you to your local one-call center to mark underground utilities.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/icons/811 icon.svg","alt":"811 Call Before You Dig","caption":"","width":"full","align":"left"},{"type":"heading","level":3,"text":"Why It Matters","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Hitting an underground utility line can cause serious injury, service disruptions, and costly repairs. A simple call to 811 ensures utilities are marked, keeping you and your community safe.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Whether you''re planting a tree, installing a fence, or starting a major construction project, calling 811 before you dig is the law in most states and is always the safe choice.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"columns","cols":2,"gap":"md","columns":[[{"type":"heading","level":2,"text":"How 811 Works","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"• Call 811 - Contact your local one-call center at least 2-3 business days before you plan to dig.\n• Wait for Marking - Utility operators will mark the approximate location of underground lines with flags or paint.\n• Respect the Marks - Use hand tools or vacuum excavation within 18-24 inches of marked utilities.\n• Dig Safely - Excavate carefully, watching for any unmarked utilities that may have been missed.","style":{"align":"left","textSize":"md","textColor":"default"}}],[{"type":"heading","level":3,"text":"Important Reminders","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• Call at least 2-3 business days before digging\n• Wait for all utilities to be marked\n• Marks are valid for a limited time\n• Call again if marks are damaged or unclear\n• Use hand tools near marked utilities","style":{"align":"left","textSize":"md","textColor":"default"}}]]}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"image","url":"https://usanorth811.org/assets/images/logo.svg","alt":"USA North 811 Logo","caption":"","width":"full","align":"left"},{"type":"heading","level":2,"text":"USA North 811 - Nevada''s Call Center","style":{"align":"center","textSize":"lg","textColor":"default"}},{"type":"text","body":"When you call 811 in Nevada, you''re connected to USA North 811, the one-call center that serves Nevada and Northern California. USA North 811 coordinates with utility operators across the state to ensure all underground utilities are properly marked before you dig.","style":{"align":"center","textSize":"md","textColor":"default"}},{"type":"text","body":"USA North 811 processes dig ticket requests, notifies utility operators of planned excavations, and helps coordinate the marking of underground facilities. They are your direct connection to the damage prevention process in Nevada.","style":{"align":"center","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Visit USA North 811","url":"https://usanorth811.org/","style":{"align":"left"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Utility Marking Color Codes","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Utility locators use standardized colors to mark different types of underground utilities.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Red","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Electric power lines, cables, conduit, and lighting cables","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Yellow","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Gas, oil, steam, petroleum, or gaseous materials","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Orange","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Communication, alarm or signal lines, cables, or conduit","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Blue","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Potable water","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Green","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Sewers and drain lines","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Purple","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Reclaimed water, irrigation, and slurry lines","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"White","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Proposed excavation limits or route","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Pink","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Temporary survey markings","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"811 Resources & Tools","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"grid","columns":3,"gap":"md","items":[{"icon":"📋","title":"Create a Ticket","body":"Request utility marking for your excavation project through your local one-call center."},{"icon":"📚","title":"Handbooks & Guides","body":"Access best practices guides, excavation handbooks, and damage prevention resources."},{"icon":"❓","title":"Common Questions","body":"Find answers to frequently asked questions about the 811 process and damage prevention."}]}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Nevada Excavation Documents","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Essential documents for safe excavation in Nevada.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"📄","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"EPR Codes","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Electronic Positive Response Codes and Descriptions for Nevada.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Download PDF","url":"https://usanorth811.org/assets/PDF/NV-EPR-Codes_Update-Announcment.pdf","style":{"align":"left"}},{"type":"text","body":"📖","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Nevada Excavation Handbook","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Comprehensive guide to safe excavation practices in Nevada (2025 edition).","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Download PDF","url":"https://usanorth811.org/assets/PDF/Nevada-2025-Handbook.pdf","style":{"align":"left"}},{"type":"text","body":"⚖️","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Nevada Excavation Law (English)","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Nevada excavation law and regulations (2025 edition).","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Download PDF","url":"https://usanorth811.org/assets/PDF/Nevada-2025-Law.pdf","style":{"align":"left"}},{"type":"text","body":"⚖️","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Nevada Excavation Law (Spanish)","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Ley de excavación de Nevada y regulaciones (versión en español).","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Descargar PDF","url":"https://usanorth811.org/assets/PDF/NV-LAW-Spanish.pdf","style":{"align":"left"}}]}]', '<!-- Main 811 Info -->
    <section class="content-section">
        <div class="container">
            <div class="call-811-card" style="max-width: 100%; margin-bottom: 4rem;">
                <div class="call-number" style="text-align: center; padding: 1rem 0;">
                    <img src="assets/images/programs/icons/811 icon.svg" alt="811 Call Before You Dig" style="max-width: 200px; width: 100%; height: auto; display: block; margin: 0 auto;">
                </div>
                <div class="call-info">
                    <h3>Why It Matters</h3>
                    <p>Hitting an underground utility line can cause serious injury, service disruptions, and costly repairs. 
                    A simple call to 811 ensures utilities are marked, keeping you and your community safe.</p>
                    <p style="margin-top: 1rem;">
                        Whether you''re planting a tree, installing a fence, or starting a major construction project, 
                        calling 811 before you dig is the law in most states and is always the safe choice.
                    </p>
                </div>
            </div>

            <div class="content-grid">
                <div class="content-text">
                    <h2>How 811 Works</h2>
                    <ol class="process-list">
                        <li>
                            <strong>Call 811</strong> - Contact your local one-call center at least 2-3 business days before you plan to dig.
                        </li>
                        <li>
                            <strong>Wait for Marking</strong> - Utility operators will mark the approximate location of underground lines with flags or paint.
                        </li>
                        <li>
                            <strong>Respect the Marks</strong> - Use hand tools or vacuum excavation within 18-24 inches of marked utilities.
                        </li>
                        <li>
                            <strong>Dig Safely</strong> - Excavate carefully, watching for any unmarked utilities that may have been missed.
                        </li>
                    </ol>
                </div>
                <div class="content-visual">
                    <div class="visual-card">
                        <h3>Important Reminders</h3>
                        <ul class="reminder-list">
                            <li>Call at least 2-3 business days before digging</li>
                            <li>Wait for all utilities to be marked</li>
                            <li>Marks are valid for a limited time</li>
                            <li>Call again if marks are damaged or unclear</li>
                            <li>Use hand tools near marked utilities</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- USA North 811 -->
    <section class="content-section bg-light">
        <div class="container">
            <div style="max-width: 800px; margin: 0 auto; text-align: center;">
                <div style="text-align: center; margin-bottom: 2rem;">
                    <img src="https://usanorth811.org/assets/images/logo.svg" alt="USA North 811 Logo" style="max-width: 250px; width: 100%; height: auto; margin: 0 auto; display: block;">
                </div>
                <h2 style="text-align: center; margin-bottom: 1.5rem;">USA North 811 - Nevada''s Call Center</h2>
                <p style="text-align: center;">
                    When you call 811 in Nevada, you''re connected to <a href="https://usanorth811.org/" target="_blank" rel="noopener noreferrer">USA North 811</a>, 
                    the one-call center that serves Nevada and Northern California. USA North 811 coordinates with utility operators across the state to ensure 
                    all underground utilities are properly marked before you dig.
                </p>
                <p style="margin-top: 1rem; text-align: center;">
                    USA North 811 processes dig ticket requests, notifies utility operators of planned excavations, and helps coordinate the marking of 
                    underground facilities. They are your direct connection to the damage prevention process in Nevada.
                </p>
                <div style="margin-top: 2rem; text-align: center;">
                    <a href="https://usanorth811.org/" target="_blank" rel="noopener noreferrer" class="btn btn-primary">Visit USA North 811</a>
                </div>
            </div>
        </div>
    </section>

    <!-- Color Codes -->
    <section class="content-section">
        <div class="container">
            <div class="section-header">
                <h2 class="section-title">Utility Marking Color Codes</h2>
                <p class="section-subtitle">Utility locators use standardized colors to mark different types of underground utilities.</p>
            </div>

            <div class="color-codes">
                <div class="color-item" style="border-left: 6px solid #FF0000;">
                    <div class="color-swatch" style="background: #FF0000;"></div>
                    <div>
                        <h3>Red</h3>
                        <p>Electric power lines, cables, conduit, and lighting cables</p>
                    </div>
                </div>
                <div class="color-item" style="border-left: 6px solid #FFD700;">
                    <div class="color-swatch" style="background: #FFD700;"></div>
                    <div>
                        <h3>Yellow</h3>
                        <p>Gas, oil, steam, petroleum, or gaseous materials</p>
                    </div>
                </div>
                <div class="color-item" style="border-left: 6px solid #FFA500;">
                    <div class="color-swatch" style="background: #FFA500;"></div>
                    <div>
                        <h3>Orange</h3>
                        <p>Communication, alarm or signal lines, cables, or conduit</p>
                    </div>
                </div>
                <div class="color-item" style="border-left: 6px solid #0000FF;">
                    <div class="color-swatch" style="background: #0000FF;"></div>
                    <div>
                        <h3>Blue</h3>
                        <p>Potable water</p>
                    </div>
                </div>
                <div class="color-item" style="border-left: 6px solid #00FF00;">
                    <div class="color-swatch" style="background: #00FF00;"></div>
                    <div>
                        <h3>Green</h3>
                        <p>Sewers and drain lines</p>
                    </div>
                </div>
                <div class="color-item" style="border-left: 6px solid #800080;">
                    <div class="color-swatch" style="background: #800080;"></div>
                    <div>
                        <h3>Purple</h3>
                        <p>Reclaimed water, irrigation, and slurry lines</p>
                    </div>
                </div>
                <div class="color-item" style="border-left: 6px solid #FFFFFF; border: 2px solid #ccc;">
                    <div class="color-swatch" style="background: #FFFFFF; border: 2px solid #ccc;"></div>
                    <div>
                        <h3>White</h3>
                        <p>Proposed excavation limits or route</p>
                    </div>
                </div>
                <div class="color-item" style="border-left: 6px solid #FF00FF;">
                    <div class="color-swatch" style="background: #FF00FF;"></div>
                    <div>
                        <h3>Pink</h3>
                        <p>Temporary survey markings</p>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- Resources -->
    <section class="content-section">
        <div class="container">
            <div class="section-header">
                <h2 class="section-title">811 Resources & Tools</h2>
            </div>

            <div class="features-grid">
                <div class="feature-item">
                    <div class="feature-icon">📋</div>
                    <h3>Create a Ticket</h3>
                    <p>Request utility marking for your excavation project through your local one-call center.</p>
                    <a href="https://usanorth811.org/" target="_blank" rel="noopener noreferrer" class="link-arrow">Get Started →</a>
                </div>
                <div class="feature-item">
                    <div class="feature-icon">📚</div>
                    <h3>Handbooks & Guides</h3>
                    <p>Access best practices guides, excavation handbooks, and damage prevention resources.</p>
                    <a href="about-811.html#nevada-excavation-documents" class="link-arrow">View Resources →</a>
                </div>
    
                <div class="feature-item">
                    <div class="feature-icon">❓</div>
                    <h3>Common Questions</h3>
                    <p>Find answers to frequently asked questions about the 811 process and damage prevention.</p>
                    <a href="about-811-questions.html" class="link-arrow">View FAQs →</a>
                </div>
            </div>
        </div>
    </section>

    <!-- Nevada Documents -->
    <section id="nevada-excavation-documents" class="content-section bg-light">
        <div class="container">
            <div class="section-header">
                <h2 class="section-title">Nevada Excavation Documents</h2>
                <p class="section-subtitle">Essential documents for safe excavation in Nevada.</p>
            </div>

            <div class="documents-grid">
                <div class="document-card">
                    <div class="document-icon">📄</div>
                    <h3>EPR Codes</h3>
                    <p>Electronic Positive Response Codes and Descriptions for Nevada.</p>
                    <a href="https://usanorth811.org/assets/PDF/NV-EPR-Codes_Update-Announcment.pdf" target="_blank" rel="noopener noreferrer" class="btn btn-outline">Download PDF</a>
                </div>
                <div class="document-card">
                    <div class="document-icon">📖</div>
                    <h3>Nevada Excavation Handbook</h3>
                    <p>Comprehensive guide to safe excavation practices in Nevada (2025 edition).</p>
                    <a href="https://usanorth811.org/assets/PDF/Nevada-2025-Handbook.pdf" target="_blank" rel="noopener noreferrer" class="btn btn-outline">Download PDF</a>
                </div>
                <div class="document-card">
                    <div class="document-icon">⚖️</div>
                    <h3>Nevada Excavation Law (English)</h3>
                    <p>Nevada excavation law and regulations (2025 edition).</p>
                    <a href="https://usanorth811.org/assets/PDF/Nevada-2025-Law.pdf" target="_blank" rel="noopener noreferrer" class="btn btn-outline">Download PDF</a>
                </div>
                <div class="document-card">
                    <div class="document-icon">⚖️</div>
                    <h3>Nevada Excavation Law (Spanish)</h3>
                    <p>Ley de excavación de Nevada y regulaciones (versión en español).</p>
                    <a href="https://usanorth811.org/assets/PDF/NV-LAW-Spanish.pdf" target="_blank" rel="noopener noreferrer" class="btn btn-outline">Descargar PDF</a>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
