     VALUES ('00000000-0000-4000-8000-000012b3e10e', 'training-database', 'Training Database', 'Training', 'Records and resources for excavator training.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"This page will host the training database. Content is editable in the staff portal under Editable pages (slug: training-database).","style":{"align":"left","textSize":"md","textColor":"default"}}]}]', '<section class="content-section">
